/* ================= STORAGE ================= */
const LS = {
  get(k, def){ try{ const v = localStorage.getItem(k); return v===null?def:JSON.parse(v); }catch(e){ return def; } },
  set(k, v){ try{ localStorage.setItem(k, JSON.stringify(v)); }catch(e){} }
};
function uid(){ return Date.now().toString(36)+Math.random().toString(36).slice(2,8); }
function todayIso(){ const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function escapeHtml(s){ return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function fmtLabel(iso){
  if(!iso) return '-';
  const hari = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
  const bulan = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
  const d = new Date(iso+'T00:00:00');
  return hari[d.getDay()]+', '+d.getDate()+' '+bulan[d.getMonth()]+' '+d.getFullYear();
}

/* ================= ICONS ================= */
const ICON_PATHS = {
  gear: '<circle cx="12" cy="12" r="3"/><path d="M19.4 13a7.97 7.97 0 000-2l2-1.5-2-3.4-2.4 1a8 8 0 00-1.7-1L15 3h-4l-.3 2.6a8 8 0 00-1.7 1l-2.4-1-2 3.4L6.6 11a7.97 7.97 0 000 2l-2 1.5 2 3.4 2.4-1a8 8 0 001.7 1L11 21h4l.3-2.6a8 8 0 001.7-1l2.4 1 2-3.4-2-1.5z"/>',
  people: '<circle cx="9" cy="8" r="3"/><path d="M3 20c0-3 2.5-5 6-5s6 2 6 5"/><circle cx="17" cy="9" r="2.3"/><path d="M15.5 15.2c2.6.3 4.5 2 4.5 4.8"/>',
  map: '<path d="M9 18l-6 3V6l6-3 6 3 6-3v15l-6 3-6-3z"/><path d="M9 3v15M15 6v15"/>',
  flask: '<path d="M9 3h6M10 3v6l-5.5 9.5A1.5 1.5 0 005.8 21h12.4a1.5 1.5 0 001.3-2.5L14 9V3"/><path d="M7.5 15h9"/>',
  trash: '<path d="M4 7h16M9 7V4h6v3M6 7l1 13a2 2 0 002 2h6a2 2 0 002-2l1-13"/><path d="M10 11v6M14 11v6"/>',
  edit: '<path d="M4 20h4L18.5 9.5a2.1 2.1 0 00-3-3L5 17v3z"/><path d="M13.5 6.5l4 4"/>',
  check: '<path d="M20 6L9 17l-5-5"/>',
  calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>',
  document: '<path d="M6 3h9l5 5v13a1 1 0 01-1 1H6a1 1 0 01-1-1V4a1 1 0 011-1z"/><path d="M14 3v5h5"/>',
  search: '<circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/>',
  chevron: '<path d="M9 18l6-6-6-6"/>'
};
function ic(name, size){
  size = size || 20;
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-5px;display:inline-block;">${ICON_PATHS[name]||''}</svg>`;
}

/* ================= DATA ================= */
let USER = LS.get('hz_user', {name:''});
let PEKERJA = LS.get('hz_pekerja', []);       // [{id, kode (2 karakter), nama}]
// Migrasi data lama (field 'nomor') -> 'kode' 2 karakter, tanpa menghapus data.
PEKERJA = PEKERJA.map(p=>{
  if(p.kode) return p;
  const k = String(p.nomor==null?'':p.nomor).toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,2) || '00';
  return {id:p.id, kode:k, nama:p.nama};
});
let BLOKS = LS.get('hz_bloks', []);           // [{id, kode}]
let HERBISIDA = LS.get('hz_herbisida', []);   // [{id, nama}]
let CATATAN = LS.get('hz_catatan', []);       // catatan kerja harian, lihat addCatatan()

function saveUser(){ LS.set('hz_user', USER); }
function savePekerja(){ LS.set('hz_pekerja', PEKERJA); }
function saveBloks(){ LS.set('hz_bloks', BLOKS); }
function saveHerbisida(){ LS.set('hz_herbisida', HERBISIDA); }
function saveCatatan(){ LS.set('hz_catatan', CATATAN); }

/* ================= NAV / DRAWER / MODAL / TOAST ================= */
function showScreen(name){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById('screen-'+name).classList.add('active');
  document.querySelectorAll('#bottomnav button').forEach(b=>b.classList.toggle('active', b.dataset.tab===name));
  document.getElementById('screens').style.padding = name==='peta' ? '0 0 90px' : '16px 16px calc(90px + env(safe-area-inset-bottom,0px))';
  const titles = {beranda:['BERANDA','Ringkasan'], catat:['CATAT KERJA','Input Hari Ini'], riwayat:['RIWAYAT','Laporan & Data'], peta:['PETA','Lokasi Blok']};
  document.getElementById('tb-eyebrow').textContent = titles[name][0];
  document.getElementById('tb-title').textContent = titles[name][1];
  if(name==='beranda') renderBeranda();
  if(name==='catat') renderCatat();
  if(name==='riwayat') renderRiwayat();
  if(name==='peta') renderPeta();
  closeDrawer();
}
function openDrawer(){
  document.getElementById('dw-name').textContent = USER.name || 'Nama belum diisi';
  document.getElementById('drawerOverlay').classList.add('show');
  document.getElementById('drawer').classList.add('show');
}
function closeDrawer(){
  document.getElementById('drawerOverlay').classList.remove('show');
  document.getElementById('drawer').classList.remove('show');
}
function openModal(html){
  document.getElementById('modalSheet').innerHTML = html;
  document.getElementById('modalOverlay').classList.add('show');
}
function closeModal(){
  document.getElementById('modalOverlay').classList.remove('show');
}
let toastTimer=null;
function toast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('show'), 1800);
}

/* ================= PENGATURAN AKUN ================= */
function openSettingAkun(){
  closeDrawer();
  openModal(`
    <div class="mhead"><h2>Pengaturan Akun</h2><button class="mclose" onclick="closeModal()">&times;</button></div>
    <label class="flabel">Nama</label>
    <input type="text" id="setUserName" value="${escapeHtml(USER.name)}" placeholder="Nama Anda">
    <button class="btn-block" onclick="saveSettingAkun()">Simpan</button>
  `);
}
function saveSettingAkun(){
  USER.name = document.getElementById('setUserName').value.trim();
  saveUser();
  toast('Tersimpan');
  closeModal();
}

/* ================= MASTER: PEKERJA ================= */
function openKelolaPekerja(){
  closeDrawer();
  renderKelolaPekerjaModal();
}
function renderKelolaPekerjaModal(){
  openModal(`
    <div class="mhead"><h2>Kelola Pekerja</h2><button class="mclose" onclick="closeModal()">&times;</button></div>
    <div class="grid2">
      <input type="text" id="newPekerjaKode" placeholder="Kode (2 karakter, mis. A1)" maxlength="2" style="text-transform:uppercase;" oninput="this.value=this.value.toUpperCase()">
      <input type="text" id="newPekerjaNama" placeholder="Nama">
    </div>
    <button class="btn-block" onclick="addPekerja()">+ Tambah Pekerja</button>
    <div class="section-eyebrow">Daftar Pekerja (${PEKERJA.length})</div>
    <div class="card card-flat">
      ${PEKERJA.length===0 ? '<div class="empty-note">Belum ada pekerja. Tambahkan di atas.</div>' :
        PEKERJA.slice().sort((a,b)=>a.kode.localeCompare(b.kode)).map(p=>`<div class="list-row"><span><b>${escapeHtml(p.kode)}</b> &middot; ${escapeHtml(p.nama)}</span><button class="icon-btn" onclick="deletePekerja('${p.id}')">${ic('trash')}</button></div>`).join('')}
    </div>
  `);
}
function addPekerja(){
  const kode = document.getElementById('newPekerjaKode').value.trim().toUpperCase();
  const nama = document.getElementById('newPekerjaNama').value.trim();
  if(!kode || !nama){ toast('Isi kode dan nama'); return; }
  if(!/^[A-Z0-9]{2}$/.test(kode)){ toast('Kode harus 2 karakter huruf/angka'); return; }
  if(PEKERJA.some(p=>p.kode===kode)){ toast('Kode ini sudah dipakai pekerja lain'); return; }
  PEKERJA.push({id:uid(), kode, nama});
  savePekerja();
  renderKelolaPekerjaModal();
  toast('Pekerja ditambahkan');
}
function deletePekerja(id){
  if(!confirm('Hapus pekerja ini dari master data?')) return;
  PEKERJA = PEKERJA.filter(p=>p.id!==id);
  savePekerja();
  renderKelolaPekerjaModal();
}

/* ================= MASTER: NO BLOK ================= */
function openKelolaBlok(){
  closeDrawer();
  renderKelolaBlokModal();
}
function renderKelolaBlokModal(){
  openModal(`
    <div class="mhead"><h2>Kelola No Blok</h2><button class="mclose" onclick="closeModal()">&times;</button></div>
    <div class="grid2">
      <input type="text" id="newBlokKode" placeholder="mis. 11 TS 32" style="margin-bottom:0;">
      <input type="text" id="newBlokLuas" placeholder="Luas (ha), opsional" inputmode="decimal" style="margin-bottom:0;">
    </div>
    <button class="btn-block" onclick="addBlok()">+ Tambah Blok</button>
    <div class="section-eyebrow">Daftar Blok (${BLOKS.length})</div>
    <div class="card card-flat">
      ${BLOKS.length===0 ? '<div class="empty-note">Belum ada blok. Tambahkan di atas.</div>' :
        BLOKS.map(b=>`<div class="list-row"><span>${escapeHtml(b.kode)}${b.luasHa?' <span class="field-sub">('+escapeHtml(b.luasHa)+' ha)</span>':''}</span><button class="icon-btn" onclick="deleteBlok('${b.id}')">${ic('trash')}</button></div>`).join('')}
    </div>
  `);
}
function addBlok(){
  const kode = document.getElementById('newBlokKode').value.trim();
  const luasHa = document.getElementById('newBlokLuas').value.trim();
  if(!kode){ toast('Isi kode blok dulu'); return; }
  if(BLOKS.some(b=>b.kode.toLowerCase()===kode.toLowerCase())){ toast('Blok ini sudah ada'); return; }
  BLOKS.push({id:uid(), kode, luasHa: luasHa?parseFloat(luasHa):null, rowSpacingCm:145});
  saveBloks();
  renderKelolaBlokModal();
  toast('Blok ditambahkan');
}
function deleteBlok(id){
  if(!confirm('Hapus blok ini?')) return;
  BLOKS = BLOKS.filter(b=>b.id!==id);
  saveBloks();
  renderKelolaBlokModal();
}

/* ================= MASTER: HERBISIDA ================= */
function openKelolaHerbisida(){
  closeDrawer();
  renderKelolaHerbisidaModal();
}
function renderKelolaHerbisidaModal(){
  openModal(`
    <div class="mhead"><h2>Kelola Herbisida</h2><button class="mclose" onclick="closeModal()">&times;</button></div>
    <div style="display:flex;gap:8px;">
      <input type="text" id="newHerbisidaNama" placeholder="Nama produk" style="margin-bottom:0;">
      <button class="pill-btn" onclick="addHerbisida()">+ Tambah</button>
    </div>
    <div class="section-eyebrow">Daftar Herbisida (${HERBISIDA.length})</div>
    <div class="card card-flat">
      ${HERBISIDA.length===0 ? '<div class="empty-note">Belum ada produk. Tambahkan di atas.</div>' :
        HERBISIDA.map(h=>`<div class="list-row"><span>${escapeHtml(h.nama)}</span><button class="icon-btn" onclick="deleteHerbisida('${h.id}')">${ic('trash')}</button></div>`).join('')}
    </div>
  `);
}
function addHerbisida(){
  const nama = document.getElementById('newHerbisidaNama').value.trim();
  if(!nama){ toast('Isi nama produk dulu'); return; }
  if(HERBISIDA.some(h=>h.nama.toLowerCase()===nama.toLowerCase())){ toast('Produk ini sudah ada'); return; }
  HERBISIDA.push({id:uid(), nama});
  saveHerbisida();
  renderKelolaHerbisidaModal();
  toast('Produk ditambahkan');
}
function deleteHerbisida(id){
  if(!confirm('Hapus produk ini?')) return;
  HERBISIDA = HERBISIDA.filter(h=>h.id!==id);
  saveHerbisida();
  renderKelolaHerbisidaModal();
}

/* ================= BERANDA ================= */
function renderBeranda(){
  const host = document.getElementById('screen-beranda');
  const todayCatatan = CATATAN.filter(c=>c.date===todayIso());
  const pekerjaHadirHariIni = new Set();
  todayCatatan.forEach(c=>(c.pekerjaHadir||[]).forEach(id=>pekerjaHadirHariIni.add(id)));
  const blokHariIni = new Set(todayCatatan.map(c=>c.blokId));

  host.innerHTML = `
    <div class="card" style="background:var(--primary);color:#fff;">
      <div style="font-size:12px;opacity:.85;">${fmtLabel(todayIso())}</div>
      <div style="font-size:18px;font-weight:800;margin-top:2px;">${escapeHtml(USER.name||'Selamat datang')}</div>
    </div>

    <button class="btn-block" onclick="showScreen('catat')">${ic('document',20)} Catat Kerja Hari Ini</button>

    <div class="section-eyebrow">Ringkasan Hari Ini</div>
    <div class="card card-tap" onclick="showScreen('catat')">
      <div class="icwrap">${ic('people')}</div>
      <div class="ctext"><div class="cval">${pekerjaHadirHariIni.size} pekerja</div><div class="clabel">Tercatat hadir hari ini</div></div>
      ${ic('chevron',18)}
    </div>
    <div class="card card-tap" onclick="showScreen('riwayat')">
      <div class="icwrap pink">${ic('map')}</div>
      <div class="ctext"><div class="cval">${blokHariIni.size} blok</div><div class="clabel">Dikerjakan hari ini</div></div>
      ${ic('chevron',18)}
    </div>
    <div class="card card-tap" onclick="showScreen('riwayat')">
      <div class="icwrap">${ic('document')}</div>
      <div class="ctext"><div class="cval">${CATATAN.length} catatan</div><div class="clabel">Riwayat & Laporan</div></div>
      ${ic('chevron',18)}
    </div>
  `;
}

/* ================= CATAT KERJA ================= */
window._draft = window._draft || null;
function resetDraft(){
  window._draft = {
    date: todayIso(), pekerjaHadir: [], blokId: '',
    statusTanaman: '', statusPekerjaan: '', statusGulma: '',
    herbisida: [], catatan: ''
  };
}
function renderCatat(){
  if(!window._draft) resetDraft();
  const d = window._draft;
  const host = document.getElementById('screen-catat');

  if(PEKERJA.length===0 || BLOKS.length===0){
    host.innerHTML = `<div class="card"><div class="empty-note">Isi dulu Kelola Pekerja &amp; Kelola No Blok lewat menu ${ic('gear',16)} di hamburger.</div></div>`;
    return;
  }

  host.innerHTML = `
  <div id="ckPager" onscroll="ckPagerScroll()">
    <div class="ck-page">
    <div class="card">
      <label class="flabel">Tanggal</label>
      <input type="date" value="${d.date}" onchange="draftSet('date', this.value)">
    </div>

    <div class="card card-tap" onclick="openAbsenModal()">
      <div class="icwrap">${ic('people')}</div>
      <div class="ctext"><div class="cval">${d.pekerjaHadir.length} pekerja</div><div class="clabel">Tap untuk isi Absen</div></div>
      ${ic('chevron',18)}
    </div>
    ${d.pekerjaHadir.length>0 ? `<div style="display:flex;flex-wrap:wrap;gap:6px;margin:-8px 0 14px;">${d.pekerjaHadir.map(id=>`<span class="badge">${escapeHtml(pekerjaLabel(id))}</span>`).join('')}</div>` : ''}

    <div class="card">
      <label class="flabel">No Blok</label>
      <select onchange="draftSet('blokId', this.value)">
        <option value="">- Pilih -</option>
        ${BLOKS.map(b=>`<option value="${b.id}" ${d.blokId===b.id?'selected':''}>${escapeHtml(b.kode)}</option>`).join('')}
      </select>
      ${d.blokId ? renderBlokInfoCard(d.blokId) : ''}

      <label class="flabel">Status Tanaman</label>
      <select onchange="draftSet('statusTanaman', this.value)">
        <option value="">- Pilih -</option>
        ${['Plantcane','Raton Cane 1','Raton Cane 2','Raton Cane 3'].map(v=>`<option value="${v}" ${d.statusTanaman===v?'selected':''}>${v}</option>`).join('')}
      </select>

      <label class="flabel">Status Pekerjaan</label>
      <select onchange="draftSet('statusPekerjaan', this.value)">
        <option value="">- Pilih -</option>
        ${['Pre-Emergence','Post 1','Post 2','Post 3'].map(v=>`<option value="${v}" ${d.statusPekerjaan===v?'selected':''}>${v}</option>`).join('')}
      </select>

      <label class="flabel">Status Gulma</label>
      <div style="display:flex;gap:8px;margin-bottom:8px;">
        ${['Ringan','Sedang','Berat'].map(v=>`<button class="chip ${d.statusGulma===v?'active':''}" onclick="draftSet('statusGulma','${v}')">${v}</button>`).join('')}
      </div>
    </div>

    <div class="card">
      <div class="section-eyebrow-row" style="margin:0 0 8px;"><span>Herbisida &amp; Dosis</span>
        <button class="pill-btn sm" onclick="addHerbisidaRow()">+ Produk</button>
      </div>
      ${d.herbisida.length===0 ? '<div class="empty-note">Belum ada produk ditambahkan.</div>' : d.herbisida.map((h,i)=>`
        <div class="grid2" style="align-items:center;">
          <select onchange="setHerbisidaRow(${i},'nama',this.value)">
            <option value="">- Pilih Produk -</option>
            ${HERBISIDA.map(x=>`<option value="${escapeHtml(x.nama)}" ${h.nama===x.nama?'selected':''}>${escapeHtml(x.nama)}</option>`).join('')}
          </select>
          <div style="display:flex;gap:6px;">
            <input type="text" placeholder="Dosis (mis. 200 ml)" value="${escapeHtml(h.dosis)}" onchange="setHerbisidaRow(${i},'dosis',this.value)">
            <button class="icon-btn" onclick="removeHerbisidaRow(${i})">${ic('trash')}</button>
          </div>
        </div>
      `).join('')}
    </div>

    <div class="card">
      <label class="flabel">Catatan <span class="field-sub">(opsional)</span></label>
      <textarea rows="2" onchange="draftSet('catatan', this.value)">${escapeHtml(d.catatan)}</textarea>
    </div>

    <button class="btn-block" onclick="saveCatatanBaru()">${ic('check',20)} Simpan Catatan Kerja</button>
    </div>
    <div class="ck-page" id="ckPage2">${renderCatatPage2(d.blokId)}</div>
  </div>
  <div style="display:flex;justify-content:center;gap:6px;margin:10px 0 2px;">
    <span id="ckDot0" class="ckdot active"></span><span id="ckDot1" class="ckdot"></span>
  </div>
  `;
  requestAnimationFrame(()=>{
    const pager = document.getElementById('ckPager');
    if(pager) pager.scrollLeft = ckActivePage * pager.clientWidth;
  });
}
let ckActivePage = 0;
function ckPagerScroll(){
  const pager = document.getElementById('ckPager');
  if(!pager || !pager.clientWidth) return;
  const idx = Math.round(pager.scrollLeft / pager.clientWidth);
  ckActivePage = idx;
  const d0 = document.getElementById('ckDot0'), d1 = document.getElementById('ckDot1');
  if(d0) d0.classList.toggle('active', idx===0);
  if(d1) d1.classList.toggle('active', idx===1);
}
function openAbsenModal(){
  openModal(`
    <div class="mhead"><h2>Absen Hari Ini</h2><button class="mclose" onclick="closeModalAbsen()">&times;</button></div>
    <input type="text" placeholder="Cari kode/nama..." oninput="filterPekerjaList(this.value)">
    <div id="pekerjaListWrap" style="max-height:50vh;overflow-y:auto;">
      ${renderPekerjaChecklist('')}
    </div>
    <button class="btn-block" style="margin-top:12px;" onclick="closeModalAbsen()">Selesai</button>
  `);
}
function closeModalAbsen(){
  closeModal();
  renderCatat();
}
function renderPekerjaChecklist(filterText){
  const q = (filterText||'').toLowerCase().trim();
  const d = window._draft;
  const list = PEKERJA.slice().sort((a,b)=>a.kode.localeCompare(b.kode))
    .filter(p=>!q || p.kode.toLowerCase().includes(q) || p.nama.toLowerCase().includes(q));
  if(list.length===0) return '<div class="empty-note">Tidak ditemukan.</div>';
  return list.map(p=>`<div class="chk-row"><input type="checkbox" id="chkPekerja-${p.id}" ${d.pekerjaHadir.includes(p.id)?'checked':''} onchange="togglePekerjaHadir('${p.id}', this.checked)"><label for="chkPekerja-${p.id}" style="margin-left:8px;">${escapeHtml(p.kode)} &middot; ${escapeHtml(p.nama)}</label></div>`).join('');
}
function filterPekerjaList(text){
  document.getElementById('pekerjaListWrap').innerHTML = renderPekerjaChecklist(text);
}
function togglePekerjaHadir(id, checked){
  const d = window._draft;
  if(checked){ if(!d.pekerjaHadir.includes(id)) d.pekerjaHadir.push(id); }
  else { d.pekerjaHadir = d.pekerjaHadir.filter(x=>x!==id); }
}
function renderBlokInfoCard(blokId){
  const pb = PETA_BLOCKS.find(p=>p.blokId===blokId);
  if(!pb) return `<div class="field-sub" style="margin:-4px 0 12px;">Blok ini belum digambar di Peta — buka tab Peta untuk menandainya (opsional).</div>`;
  const xs = pb.points.map(p=>p.x), ys = pb.points.map(p=>p.y);
  const minX=Math.min(...xs), maxX=Math.max(...xs), minY=Math.min(...ys), maxY=Math.max(...ys);
  const pad = 4;
  const vb = `${minX-pad} ${minY-pad} ${(maxX-minX)+pad*2} ${(maxY-minY)+pad*2}`;
  const has = pb.rowP1 && pb.rowP2;
  const est = estimateRows(pb);
  if(est) syncBlockRows(pb);
  return `
    <div class="card card-flat" style="padding:10px;margin:-2px 0 12px;">
      <svg viewBox="${vb}" style="width:100%;height:90px;background:#F3EDE0;border-radius:10px;">
        <polygon points="${pb.points.map(p=>p.x+','+p.y).join(' ')}" fill="rgba(47,107,79,0.25)" stroke="#2F6B4F" stroke-width="0.15" vector-effect="non-scaling-stroke"></polygon>
        ${has?`<line x1="${pb.rowP1.x}" y1="${pb.rowP1.y}" x2="${pb.rowP2.x}" y2="${pb.rowP2.y}" stroke="#7A2E38" stroke-width="0.25" vector-effect="non-scaling-stroke"></line>`:''}
      </svg>
      <div class="field-sub" style="margin-top:6px;">${has && est ? `Perkiraan &plusmn; <b>${est.jumlahRow} row</b> (jarak ${est.spacingCm}cm)` : has ? 'Arah row ditandai, tapi Luas (ha) belum diisi untuk hitung perkiraan.' : 'Bentuk blok sudah ada, arah row belum ditandai (buka tab Peta).'}</div>
    </div>
  `;
}
function draftSet(key, val){
  window._draft[key] = val;
  renderCatat();
}
function addHerbisidaRow(){
  window._draft.herbisida.push({nama:'', dosis:''});
  renderCatat();
}
function setHerbisidaRow(i, key, val){
  window._draft.herbisida[i][key] = val;
}
function removeHerbisidaRow(i){
  window._draft.herbisida.splice(i,1);
  renderCatat();
}
function saveCatatanBaru(){
  const d = window._draft;
  if(!d.blokId){ toast('Pilih No Blok dulu'); return; }
  if(d.pekerjaHadir.length===0){ toast('Tandai minimal 1 pekerja hadir'); return; }
  CATATAN.push({
    id: uid(), date: d.date, blokId: d.blokId,
    statusTanaman: d.statusTanaman, statusPekerjaan: d.statusPekerjaan, statusGulma: d.statusGulma,
    herbisida: d.herbisida.filter(h=>h.nama), pekerjaHadir: d.pekerjaHadir.slice(), catatan: d.catatan
  });
  saveCatatan();
  toast('Catatan kerja disimpan');
  resetDraft();
  showScreen('riwayat');
}

/* ================= CATAT KERJA — HALAMAN 2 (gambar blok + assignment row) ================= */
let ck2ZoomScale=1, ck2ZoomX=0, ck2ZoomY=0, ck2TouchState={}, ck2LastBlokId=null;
let ck2CaptureMode=false, ck2CapturePoints=[], ck2ViewBox=null, ck2CapturePetaId=null;
function computeRowLines(pb, est){
  const dx = pb.rowP2.x-pb.rowP1.x, dy = pb.rowP2.y-pb.rowP1.y;
  const len = Math.hypot(dx,dy)||1;
  const dirX = dx/len, dirY = dy/len;
  let perpX = -dirY, perpY = dirX;
  if(pb.rowFlipped){ perpX=-perpX; perpY=-perpY; }
  const spacingU = ((est.spacingCm/100) / est.meterPerPctLinear) || 1;
  const projs = pb.points.map(p=>(p.x-pb.rowP1.x)*perpX + (p.y-pb.rowP1.y)*perpY);
  const minP = Math.min(...projs), maxP = Math.max(...projs);
  const L = 500;
  const lines = [];
  for(let k=0;k<est.jumlahRow;k++){
    const offset = minP + spacingU*(k+0.5);
    if(offset>maxP+spacingU) break;
    const cx = pb.rowP1.x + perpX*offset, cy = pb.rowP1.y + perpY*offset;
    lines.push({x1:cx-dirX*L, y1:cy-dirY*L, x2:cx+dirX*L, y2:cy+dirY*L, w: spacingU*0.8, idx:k});
  }
  return lines;
}
function renderCatatPage2(blokId){
  if(blokId !== ck2LastBlokId){ ck2ZoomScale=1; ck2ZoomX=0; ck2ZoomY=0; ck2LastBlokId=blokId; ck2CaptureMode=false; ck2CapturePoints=[]; }
  if(!blokId) return `<div class="card"><div class="empty-note">Pilih No Blok dulu di halaman 1.</div></div>`;
  const pb = PETA_BLOCKS.find(p=>p.blokId===blokId);
  if(!pb){
    return `<div class="card"><div class="empty-note" style="margin-bottom:10px;">Blok ini belum digambar di Peta.</div></div><button class="btn-block outline" onclick="showScreen('peta')">Pilih di Peta</button>`;
  }
  const xs = pb.points.map(p=>p.x), ys = pb.points.map(p=>p.y);
  const minX=Math.min(...xs), maxX=Math.max(...xs), minY=Math.min(...ys), maxY=Math.max(...ys);
  const pad = 6;
  const vbX=minX-pad, vbY=minY-pad, vbW=(maxX-minX)+pad*2, vbH=(maxY-minY)+pad*2;
  ck2ViewBox = {x:vbX, y:vbY, w:vbW, h:vbH};
  const vb = `${vbX} ${vbY} ${vbW} ${vbH}`;

  if(!pb.rowP1 || !pb.rowP2 || (ck2CaptureMode && ck2CapturePetaId===pb.id)){
    const capturing = ck2CaptureMode && ck2CapturePetaId===pb.id;
    return `
      <div id="ck2ImgWrap" style="position:relative;overflow:hidden;margin:-2px -16px 0;height:340px;background:#F3EDE0;touch-action:none;"
        ontouchstart="ck2TouchStart(event)" ontouchmove="ck2TouchMove(event)" ontouchend="ck2TouchEnd(event)" onclick="ck2Tap(event)">
        <div id="ck2ImgInner" style="width:100%;height:100%;position:relative;transform-origin:center center;transform:scale(${ck2ZoomScale}) translate(${ck2ZoomX}px,${ck2ZoomY}px);">
          <svg viewBox="${vb}" preserveAspectRatio="none" style="width:100%;height:100%;">
            <polygon points="${pb.points.map(p=>p.x+','+p.y).join(' ')}" fill="rgba(47,107,79,0.2)" stroke="#2F6B4F" stroke-width="0.2" vector-effect="non-scaling-stroke"></polygon>
            ${capturing && ck2CapturePoints.length===2 ? `<line x1="${ck2CapturePoints[0].x}" y1="${ck2CapturePoints[0].y}" x2="${ck2CapturePoints[1].x}" y2="${ck2CapturePoints[1].y}" stroke="#0B6FE0" stroke-width="0.3" vector-effect="non-scaling-stroke"></line>` : ''}
          </svg>
          ${capturing && ck2CapturePoints.length>0 ? ck2CapturePoints.map(p=>markerDotHtml((((p.x-vbX)/vbW)*100).toFixed(3), (((p.y-vbY)/vbH)*100).toFixed(3), ck2ZoomScale, '%')).join('') : ''}
        </div>
      </div>
      ${capturing ? `
        <div class="field-sub" style="text-align:center;margin:8px 0;">Tap 2 titik di gambar mengikuti arah row (titik ke-${ck2CapturePoints.length+1} dari 2)</div>
        <button class="pill-btn outline" style="width:100%;justify-content:center;" onclick="ck2CancelCapture()">Batal Menandai</button>
      ` : `
        <div class="card"><div class="empty-note" style="margin-bottom:10px;">Arah row belum ditandai untuk blok ini.</div></div>
        <button class="btn-block" onclick="ck2StartCapture('${pb.id}')">Tandai Arah Row di Sini</button>
      `}
    `;
  }

  const est = estimateRows(pb);
  const rows = syncBlockRows(pb);
  if(!est || rows.length===0){
    return `<div class="card"><div class="empty-note">Luas (ha) blok ini belum diisi — jumlah row belum bisa dihitung. Isi dulu lewat Kelola No Blok.</div></div>`;
  }
  const rowLines = computeRowLines(pb, est);
  const statusColor = {putih:'rgba(255,255,255,0.12)', hijau:'#3E9B6B', merah:'#B3323C'};
  const datalistOpts = PEKERJA.slice().sort((a,b)=>a.kode.localeCompare(b.kode)).map(p=>`<option value="${escapeHtml(p.kode)}">${escapeHtml(p.kode)} - ${escapeHtml(p.nama)}</option>`).join('');
  return `
    <div id="ck2ImgWrap" style="position:relative;overflow:hidden;margin:-2px -16px 0;height:340px;background:#F3EDE0;touch-action:none;"
      ontouchstart="ck2TouchStart(event)" ontouchmove="ck2TouchMove(event)" ontouchend="ck2TouchEnd(event)">
      <div id="ck2ImgInner" style="width:100%;height:100%;transform-origin:center center;transform:scale(${ck2ZoomScale}) translate(${ck2ZoomX}px,${ck2ZoomY}px);">
        <svg viewBox="${vb}" preserveAspectRatio="none" style="width:100%;height:100%;">
          <defs><clipPath id="ck2clip"><polygon points="${pb.points.map(p=>p.x+','+p.y).join(' ')}"></polygon></clipPath></defs>
          <polygon points="${pb.points.map(p=>p.x+','+p.y).join(' ')}" fill="rgba(47,107,79,0.18)" stroke="#2F6B4F" stroke-width="0.2" vector-effect="non-scaling-stroke"></polygon>
          <g clip-path="url(#ck2clip)">
            ${rowLines.map(l=>`<line x1="${l.x1}" y1="${l.y1}" x2="${l.x2}" y2="${l.y2}" stroke="${statusColor[rows[l.idx].status]||statusColor.putih}" stroke-width="${l.w}"></line>`).join('')}
          </g>
          <line x1="${pb.rowP1.x}" y1="${pb.rowP1.y}" x2="${pb.rowP2.x}" y2="${pb.rowP2.y}" stroke="#7A2E38" stroke-width="0.3" stroke-dasharray="1,1" vector-effect="non-scaling-stroke"></line>
        </svg>
      </div>
      <div style="position:absolute;left:10px;bottom:8px;background:rgba(0,0,0,.45);color:#fff;font-size:11px;padding:4px 9px;border-radius:100px;">${rows.length} row &middot; jarak ${est.spacingCm}cm &middot; cubit utk zoom</div>
    </div>
    <div style="display:flex;gap:8px;margin-top:8px;">
      <button class="pill-btn outline sm" style="flex:1;justify-content:center;" onclick="ck2StartCapture('${pb.id}')">Tandai Ulang Arah Row</button>
      <button class="pill-btn outline sm" style="flex:1;justify-content:center;" onclick="ck2FlipStart('${pb.id}')">&#8646; Row 1 di Sisi Lain</button>
    </div>

    <datalist id="ck2PekerjaList">${datalistOpts}</datalist>
    <div class="section-eyebrow" style="margin-top:12px;">Assignment Kode Pekerja per Row</div>
    <div style="overflow-x:auto;-webkit-overflow-scrolling:touch;border:1px solid var(--outline-variant);border-radius:14px;">
      <table style="border-collapse:collapse;width:max-content;">
        <tr>
          ${rows.map((r,i)=>`<td style="padding:6px 5px;text-align:center;border-right:1px solid var(--outline-variant);vertical-align:top;">
            <div onclick="showRowHistory('${pb.id}',${i})" style="font-size:11px;font-weight:800;margin-bottom:4px;cursor:pointer;color:var(--on-surface-variant);">${i+1}</div>
            <input list="ck2PekerjaList" value="${escapeHtml(r.kode||'')}" maxlength="2" style="width:60px;min-height:44px;margin:0;padding:4px;text-align:center;text-transform:uppercase;font-weight:700;font-size:16px;border-bottom:3px solid ${r.status==='merah'?'#B3323C':r.status==='hijau'?'#3E9B6B':'var(--outline)'};"
              onchange="setRowKode('${pb.id}',${i},this.value)">
          </td>`).join('')}
        </tr>
      </table>
    </div>
    <div class="field-sub" style="margin-top:6px;">Ketik kode pekerja per row (harus sudah ada di Kelola Pekerja). Hapus isi kolom = batalkan assignment. Tap nomor row untuk lihat histori.</div>
  `;
}
function ck2StartCapture(petaId){
  ck2CaptureMode = true; ck2CapturePoints = []; ck2CapturePetaId = petaId;
  refreshCk2(PETA_BLOCKS.find(x=>x.id===petaId)?.blokId);
}
function ck2CancelCapture(){
  const blokId = PETA_BLOCKS.find(x=>x.id===ck2CapturePetaId)?.blokId;
  ck2CaptureMode = false; ck2CapturePoints = []; ck2CapturePetaId = null;
  refreshCk2(blokId);
}
function ck2FlipStart(petaId){
  const pb = PETA_BLOCKS.find(x=>x.id===petaId); if(!pb) return;
  pb.rowFlipped = !pb.rowFlipped;
  savePetaBlocks();
  refreshCk2(pb.blokId);
}
function ck2Tap(evt){
  if(ck2TouchState && ck2TouchState.moved) return;
  if(!ck2CaptureMode || !ck2ViewBox) return;
  const wrap = document.getElementById('ck2ImgWrap');
  const rect = wrap.getBoundingClientRect();
  const touch = evt.changedTouches ? evt.changedTouches[0] : evt;
  const screenX = touch.clientX - rect.left, screenY = touch.clientY - rect.top;
  const localX = rect.width/2 + (screenX-rect.width/2)/ck2ZoomScale - ck2ZoomX;
  const localY = rect.height/2 + (screenY-rect.height/2)/ck2ZoomScale - ck2ZoomY;
  const x = (localX/rect.width)*ck2ViewBox.w + ck2ViewBox.x;
  const y = (localY/rect.height)*ck2ViewBox.h + ck2ViewBox.y;
  ck2CapturePoints.push({x, y});
  if(ck2CapturePoints.length>=2){
    const pb = PETA_BLOCKS.find(p=>p.id===ck2CapturePetaId);
    if(pb){
      pb.rowP1 = ck2CapturePoints[0]; pb.rowP2 = ck2CapturePoints[1];
      savePetaBlocks();
      toast('Arah row disimpan');
    }
    ck2CaptureMode = false; ck2CapturePoints = []; ck2CapturePetaId = null;
    refreshCk2(pb?pb.blokId:null);
    return;
  }
  refreshCk2(PETA_BLOCKS.find(p=>p.id===ck2CapturePetaId)?.blokId);
}
function refreshCk2(blokId){
  const el = document.getElementById('ckPage2');
  if(el) el.innerHTML = renderCatatPage2(blokId);
}
function setRowKode(petaId, rowIdx, val){
  const pb = PETA_BLOCKS.find(x=>x.id===petaId);
  if(!pb || !pb.rows || !pb.rows[rowIdx]) return;
  const kode = (val||'').trim().toUpperCase();
  const row = pb.rows[rowIdx];
  if(!kode){
    row.kode = null; row.status = 'putih';
    savePetaBlocks(); refreshCk2(pb.blokId); return;
  }
  if(!/^[A-Z0-9]{2}$/.test(kode)){ toast('Kode harus 2 karakter'); refreshCk2(pb.blokId); return; }
  if(!PEKERJA.some(p=>p.kode===kode)){ toast('Kode pekerja tidak ditemukan di Kelola Pekerja'); refreshCk2(pb.blokId); return; }
  row.kode = kode;
  row.status = 'merah';
  row.history = row.history || [];
  row.history.push({kode, ts: Date.now()});
  savePetaBlocks();
  refreshCk2(pb.blokId);
}
function pekerjaNamaByKode(kode){ const p = PEKERJA.find(x=>x.kode===kode); return p?p.nama:'-'; }
function showRowHistory(petaId, rowIdx){
  const pb = PETA_BLOCKS.find(x=>x.id===petaId);
  if(!pb || !pb.rows || !pb.rows[rowIdx]) return;
  const hist = pb.rows[rowIdx].history || [];
  openModal(`
    <div class="mhead"><h2>Histori Row ${rowIdx+1}</h2><button class="mclose" onclick="closeModal()">&times;</button></div>
    ${hist.length===0 ? '<div class="empty-note">Belum ada histori pengerjaan.</div>' :
      hist.slice().reverse().map(h=>`<div class="list-row"><span><b>${escapeHtml(h.kode)}</b> &middot; ${escapeHtml(pekerjaNamaByKode(h.kode))}</span><span class="field-sub">${new Date(h.ts).toLocaleString('id-ID',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</span></div>`).join('')}
  `);
}
function ck2Clamp(){
  const wrap = document.getElementById('ck2ImgWrap');
  if(!wrap) return;
  const rect = wrap.getBoundingClientRect();
  if(!rect.width || !rect.height) return;
  const maxX = rect.width*(ck2ZoomScale-1)/(2*ck2ZoomScale);
  const maxY = rect.height*(ck2ZoomScale-1)/(2*ck2ZoomScale);
  ck2ZoomX = Math.max(-maxX, Math.min(maxX, ck2ZoomX));
  ck2ZoomY = Math.max(-maxY, Math.min(maxY, ck2ZoomY));
}
function ck2TouchStart(evt){
  ck2TouchState.moved = false;
  if(evt.touches.length===2){
    const d = Math.hypot(evt.touches[0].clientX-evt.touches[1].clientX, evt.touches[0].clientY-evt.touches[1].clientY);
    ck2TouchState.startDist = d; ck2TouchState.startScale = ck2ZoomScale;
  } else if(evt.touches.length===1){
    ck2TouchState.startX = evt.touches[0].clientX; ck2TouchState.startY = evt.touches[0].clientY;
    ck2TouchState.baseX = ck2ZoomX; ck2TouchState.baseY = ck2ZoomY;
  }
}
function ck2TouchMove(evt){
  if(evt.touches.length===2 && ck2TouchState.startDist){
    evt.preventDefault();
    const d = Math.hypot(evt.touches[0].clientX-evt.touches[1].clientX, evt.touches[0].clientY-evt.touches[1].clientY);
    ck2ZoomScale = Math.min(20, Math.max(1, ck2TouchState.startScale * (d/ck2TouchState.startDist)));
    ck2TouchState.moved = true;
    ck2Clamp();
    const el = document.getElementById('ck2ImgInner'); if(el) el.style.transform = `scale(${ck2ZoomScale}) translate(${ck2ZoomX}px,${ck2ZoomY}px)`;
  } else if(evt.touches.length===1 && ck2TouchState.startX!==undefined && ck2ZoomScale>1){
    evt.preventDefault();
    const dx = (evt.touches[0].clientX - ck2TouchState.startX)/ck2ZoomScale;
    const dy = (evt.touches[0].clientY - ck2TouchState.startY)/ck2ZoomScale;
    if(Math.abs(dx)>3||Math.abs(dy)>3) ck2TouchState.moved = true;
    ck2ZoomX = ck2TouchState.baseX + dx; ck2ZoomY = ck2TouchState.baseY + dy;
    ck2Clamp();
    const el = document.getElementById('ck2ImgInner'); if(el) el.style.transform = `scale(${ck2ZoomScale}) translate(${ck2ZoomX}px,${ck2ZoomY}px)`;
  }
}
function ck2TouchEnd(evt){
  ck2TouchState.startDist = null; ck2TouchState.startX = undefined;
  if(ck2ZoomScale<=1){ ck2ZoomScale=1; ck2ZoomX=0; ck2ZoomY=0; const el=document.getElementById('ck2ImgInner'); if(el) el.style.transform = `scale(1) translate(0px,0px)`; }
}

/* ================= RIWAYAT ================= */
let expandedCatatanId = null;
function blokLabel(id){ const b = BLOKS.find(x=>x.id===id); return b?b.kode:'-'; }
function pekerjaLabel(id){ const p = PEKERJA.find(x=>x.id===id); return p?(p.kode+' '+p.nama):'-'; }
function toggleCatatanRow(id){
  expandedCatatanId = (expandedCatatanId===id) ? null : id;
  renderRiwayat();
}
function editCatatanField(id, key, val){
  const idx = CATATAN.findIndex(c=>c.id===id); if(idx<0) return;
  CATATAN[idx][key] = val;
  saveCatatan();
  toast('Tersimpan');
  expandedCatatanId = id;
  renderRiwayat();
}
function deleteCatatan(id){
  if(!confirm('Hapus catatan kerja ini?')) return;
  CATATAN = CATATAN.filter(c=>c.id!==id);
  saveCatatan();
  renderRiwayat();
}
function renderRiwayat(){
  const host = document.getElementById('screen-riwayat');
  const list = CATATAN.slice().sort((a,b)=>b.date.localeCompare(a.date));
  if(list.length===0){
    host.innerHTML = `<div class="card"><div class="empty-note">Belum ada catatan kerja. Mulai dari tab "Catat Kerja".</div></div>`;
    return;
  }
  host.innerHTML = list.map(c=>{
    const expanded = expandedCatatanId===c.id;
    return `<div class="card">
      <div style="display:flex;justify-content:space-between;align-items:center;cursor:pointer;" onclick="toggleCatatanRow('${c.id}')">
        <div>
          <div style="font-weight:700;">${escapeHtml(blokLabel(c.blokId))} &middot; ${fmtLabel(c.date)}</div>
          <div class="field-sub">${escapeHtml(c.statusPekerjaan||'-')} &middot; ${(c.pekerjaHadir||[]).length} pekerja</div>
        </div>
        <span class="icon-btn">${ic('edit')}</span>
      </div>
      ${expanded ? `
        <div style="margin-top:12px;">
          <label class="flabel">No Blok</label>
          <select onchange="editCatatanField('${c.id}','blokId',this.value)">
            ${BLOKS.map(b=>`<option value="${b.id}" ${c.blokId===b.id?'selected':''}>${escapeHtml(b.kode)}</option>`).join('')}
          </select>
          <label class="flabel">Status Tanaman</label>
          <select onchange="editCatatanField('${c.id}','statusTanaman',this.value)">
            ${['Plantcane','Raton Cane 1','Raton Cane 2','Raton Cane 3'].map(v=>`<option value="${v}" ${c.statusTanaman===v?'selected':''}>${v}</option>`).join('')}
          </select>
          <label class="flabel">Status Pekerjaan</label>
          <select onchange="editCatatanField('${c.id}','statusPekerjaan',this.value)">
            ${['Pre-Emergence','Post 1','Post 2','Post 3'].map(v=>`<option value="${v}" ${c.statusPekerjaan===v?'selected':''}>${v}</option>`).join('')}
          </select>
          <label class="flabel">Status Gulma</label>
          <select onchange="editCatatanField('${c.id}','statusGulma',this.value)">
            ${['Ringan','Sedang','Berat'].map(v=>`<option value="${v}" ${c.statusGulma===v?'selected':''}>${v}</option>`).join('')}
          </select>
          <label class="flabel">Herbisida</label>
          <div class="field-sub" style="margin-bottom:8px;">${(c.herbisida||[]).length? c.herbisida.map(h=>escapeHtml(h.nama)+' ('+escapeHtml(h.dosis)+')').join(', ') : '-'}</div>
          <label class="flabel">Pekerja Hadir</label>
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;">
            ${(c.pekerjaHadir||[]).map(pid=>`<span class="badge">${escapeHtml(pekerjaLabel(pid))}</span>`).join('')}
          </div>
          <label class="flabel">Catatan</label>
          <textarea rows="2" onchange="editCatatanField('${c.id}','catatan',this.value)">${escapeHtml(c.catatan||'')}</textarea>
          <div style="display:flex;gap:8px;margin-top:8px;">
            <button class="btn-block" style="flex:1;" onclick="toggleCatatanRow('${c.id}')">Selesai</button>
            <button class="pill-btn outline" onclick="deleteCatatan('${c.id}')">Hapus</button>
          </div>
        </div>
      ` : ''}
    </div>`;
  }).join('');
}

/* ================= PETA ================= */
const IDB_NAME='hzplant_db', IDB_STORE='images';
function idbOpen(){ return new Promise((res,rej)=>{ const req=indexedDB.open(IDB_NAME,1); req.onupgradeneeded=()=>{ req.result.createObjectStore(IDB_STORE); }; req.onsuccess=()=>res(req.result); req.onerror=()=>rej(req.error); }); }
async function idbSet(key, val){ const db=await idbOpen(); return new Promise((res,rej)=>{ const tx=db.transaction(IDB_STORE,'readwrite'); tx.objectStore(IDB_STORE).put(val,key); tx.oncomplete=()=>res(); tx.onerror=()=>rej(tx.error); }); }
async function idbGet(key){ const db=await idbOpen(); return new Promise((res,rej)=>{ const tx=db.transaction(IDB_STORE,'readonly'); const req=tx.objectStore(IDB_STORE).get(key); req.onsuccess=()=>res(req.result); req.onerror=()=>rej(req.error); }); }

